@Override public void onReceive(Context context,Intent intent){
  try {
    boolean sameAccount=isSameAccount(intent);
    String downloadedRemotePath=intent.getStringExtra(FileDownloader.EXTRA_REMOTE_PATH);
    String downloadBehaviour=intent.getStringExtra(OCFileListFragment.DOWNLOAD_BEHAVIOUR);
    boolean isDescendant=isDescendant(downloadedRemotePath);
    if (sameAccount && isDescendant) {
      String linkedToRemotePath=intent.getStringExtra(FileDownloader.EXTRA_LINKED_TO_PATH);
      if (linkedToRemotePath == null || isAscendant(linkedToRemotePath)) {
        refreshListOfFilesFragment(false);
      }
      refreshSecondFragment(intent.getAction(),downloadedRemotePath,intent.getBooleanExtra(FileDownloader.EXTRA_DOWNLOAD_RESULT,false));
    }
    if (mWaitingToSend != null) {
      mWaitingToSend=getStorageManager().getFileByPath(mWaitingToSend.getRemotePath());
      if (mWaitingToSend.isDown() && downloadBehaviour != null) {
        try {
          switch (downloadBehaviour) {
            case OCFileListFragment.DOWNLOAD_SEND:          sendDownloadedFile();
              break;
            case OCFileListFragment.DOWNLOAD_SET_AS:      setPictureAs();
              break;
            default:  break;
          }
        } catch (NumberFormatException e) {
          // 处理数字格式异常
          e.printStackTrace();
        }
      }
    }
  } finally {
    if (intent != null) {
      removeStickyBroadcast(intent);
    }
  }
}
